head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31200";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "font_136", attr: "__html", fn: function () { return ([String(dma_Cal1.get("O_PRE_MON")), String(dma_Cal1.get("O_PRE_DAY"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("ㆍ기산일로부터 1개월 전일 : " + String(dma_Cal1.get("O_PRE_MON")) + "<br/> ㆍ기산일(이사회결의 전일) : " + String(dma_Cal1.get("O_PRE_DAY")) + "<br/>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_O_PRE_MON", fn: function(){ return (!(String(((dma_Cal1.get("O_PRE_MON") ?? (() => { throw new Error("unresolved:" + "Cal1.O_PRE_MON"); })())) == null ? '' : ((dma_Cal1.get("O_PRE_MON") ?? (() => { throw new Error("unresolved:" + "Cal1.O_PRE_MON"); })()))).length === 0)); } }, { id: "tr_133", fn: function(){ return (!(String(((dma_Cal1.get("O_PRE_MON") ?? (() => { throw new Error("unresolved:" + "Cal1.O_PRE_MON"); })())) == null ? '' : ((dma_Cal1.get("O_PRE_MON") ?? (() => { throw new Error("unresolved:" + "Cal1.O_PRE_MON"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
};

// [A] 초기 목록 미해결 — jldstf31200: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31200' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf31200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_72_onclick
 * @description img_72 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_72_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31200.img_72_onclick' }); }
};

/**
 * @method
 * @name img_72_onmouseover
 * @description img_72 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_72_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31200.img_72_onmouseover' }); }
};

/**
 * @method
 * @name ipt_amount_onkeydown
 * @description ipt_amount 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_amount_onkeydown = function(e){
    try {
        return scwin.checkNum();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31200.ipt_amount_onkeydown' }); }
};

/**
 * @method
 * @name btn_Cal1_onclick
 * @description btn_Cal1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal1_onclick = async function(e){
    try {
        await scwin.cal1()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31200.btn_Cal1_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_onclick
 * @description btn_ExcelDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_onclick = async function(e){
    try {
        await scwin.excelDown('excelData1')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31200.btn_ExcelDown_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Cal1
 * @description Cal1 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal1 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal1"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal1", unresolved: "action:self_submit:tx_fn_Cal1" };
};

/**
 * @method
 * @name tx_fn_ExcelDown
 * @description Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_test_xhr
 * @description test xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_test_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_test_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_test_xhr", unresolved: "action:self_submit:tx_test_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getX
 * @description get X 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getX = async function (obj) {
    await $c.win.alert(obj.offsetLeft);
    await $c.win.alert(obj.offsetTop);
};

/**
 * @method
 * @name cal1
 * @description cal1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal1 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('ipt_amount').getValue() == null ? '' : String($c.util.getComponent('ipt_amount').getValue())) === '') {
        await $c.win.alert("[취득/처분 예정수량]을 입력하세요.");
        $c.util.getComponent("ipt_amount").focus();
        return;
    }
    if (($c.util.getComponent('cal_decisionDate').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDate').getValue())) === '') {
        await $c.win.alert("[관련 이사회결의일]을 입력하세요.");
        $c.util.getComponent("cal_decisionDate").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal1Req').set('method', "processCalculateRelatedDisclosure1");
    await scwin.tx_fn_Cal1();
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkNum = function () {
    if (event.keyCode === 8 || event.keyCode === 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @param {String} tableID tableID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function (tableID) {
    if (tableID.rows.length === 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal1Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    scwin.form_frmISU_CD.action = "/bizspt/excelDown.jsp";
    await scwin.tx_fn_ExcelDown();
};

/**
 * @method
 * @name test
 * @description test 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.test = async function () {
    (document.isuForm || { elements: [] }).action = "/CalculateRelatedDisclosure.do?method=processCalculateStockChangeRate";
    const returnVal = await scwin.tx_test_xhr();
    await $c.win.alert(returnVal);
};
